@keyframes pulseGlow {
  0%, 100% {
    box-shadow: 0 0 15px rgba(0, 220, 130, 0.2);
    transform: scale(1);
  }
  50% {
    box-shadow: 0 0 30px rgba(0, 220, 130, 0.6);
    transform: scale(1.03);
  }
}

.pulse-card {
  animation: pulseGlow 2s infinite ease-in-out;
}

.video-wrapper {
  width: 100%;
  aspect-ratio: 16 / 9;
  background-color: #0F172A;
  border-radius: 1rem;
}

.avatar-square {
  width: 64px;
  aspect-ratio: 1 / 1;
}

.nuxt-hero-surface {
  background: radial-gradient(circle at 50% 0%, rgba(0, 220, 130, 0.15) 0%, #020420 70%);
