}

.nuxt-glow-button:hover {
  box-shadow: 0 0 35px 2px rgba(0, 220, 130, 0.6);
}

.brand-accent-text {
  color: #00DC82; /* اللون الأخضر الزمردي الرسمي لـ Nuxt */
}

.muted-caption {
  color: #94A3B8; /* رمادي خافت للقراءات الهادئة */
}

.clickable-card {
  cursor: pointer; /* مؤشر اليد للإشارة لقابلية النقر */
}

.disabled-button {
  cursor: not-allowed; /* مؤشر المنع للحالات المعطلة */
  opacity: 0.6;
}

.custom-flex-row {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.hidden-element {
  display: none; /* إخفاء العنصر بالكامل من شجرة العرض */
}

.blurred-backdrop {
  filter: blur(8px);
}

.glowing-logo {
  /* إسقاط ظل يتبع بالضبط منحنيات وتفريغ وسم SVG */
  filter: drop-shadow(0 0 12px rgba(0, 220, 130, 0.6));
}

