.header-navbar {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  gap: 1.5rem;
}

.buttons-group {
  display: flex;
  gap: 0.75rem; /* 12px مسافة نظيفة بين جميع الأزرار */
}

.cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem 2rem; /* فواصل مختلفة للصفوف والأعمدة */
}

.app-workspace {
  display: grid;
  grid-template-columns: 4fr 8fr; /* تقسيم 12 عمود: 4 للقائمة و 8 للتفاصيل */
  gap: 1.5rem;
}

@media (max-width: 1024px) {
  .app-workspace {
    grid-template-columns: 1fr; /* عمود واحد في شاشات الجوال */
  }
}

.nav-pill:hover {
  background-color: rgba(0, 220, 130, 0.15);
  border-color: #00DC82;
}

.search-input:focus {
  outline: none;
  border-color: #00DC82;
  box-shadow: 0 0 0 3px rgba(0, 220, 130, 0.25);
}

.center-everything {
  display: flex;
  justify-content: center; /* توسيط أفقي على المحور الرئيسي */
  align-items: center;     /* توسيط عمودي على المحور المتعامد */
  min-height: 200px;
}

