  scrollbar-width: thin;
}

.search-wrapper {
  position: relative; /* نقطة مرجعية لأيقونة البحث وأزرار المسح */
}

.search-glass-icon {
  position: absolute;
  right: 1rem;
  top: 50%;
  transform: translateY(-50%); /* محاذاة في المنتصف الرأسي تماماً */
}

html {
  scroll-behavior: smooth; /* تمرير ناعم ومريح لكافة روابط الصفحة */
}

.lexicon-container {
  scroll-behavior: smooth;
}

.interactive-btn {
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.interactive-btn:hover {
  transform: translateY(-2px) scale(1.02);
}

.interactive-btn:active {
  transform: translateY(0) scale(0.98);
}

.no-select-btn {
  user-select: none; /* منع تحديد النص باللون الأزرق أثناء النقر */
  -webkit-user-select: none;
}

.code-block {
  user-select: all;  /* تحديد الكود بالكامل بنقرة واحدة لتسهيل النسخ */
}

.container-responsive {
  width: 100%;
  max-width: 1400px; /* سقف عرض أقصى لمنع تمدد الصفحة المفرط في الشاشات العريضة */
